Q: How to create markup extensions having bindable properties? A: <p>[Edit/Rewrite 30 Jan 2026]</p>
<p>With CommunityToolkit.Maui 14.0 and the new [BindableProperty] attribute, the solution is much simpler: register an <code>OnPropertyChanged</code> handler and update the markup extension's return value. I've refactored a reusable <code>BindableObjectMarkupExtension</code> to support this pattern.</p>
<pre class="lang-cs prettyprint-override"><code>using CommunityToolkit.Maui;
[ContentProperty(nameof(R))]
[RequireService([typeof(IReferenceProvider), typeof(IProvideValueTarget)])]
public partial class RgbColorExtension : BindableObjectMarkupExtension&lt;Color&gt;
{
    [BindableProperty(PropertyChangedMethodName = nameof(OnPropertyChanged))]
    public partial float R { get; set; } = 0.0f;
    [BindableProperty(PropertyChangedMethodName = nameof(OnPropertyChanged))]
    public partial float G { get; set; } = 0.0f;
    [BindableProperty(PropertyChangedMethodName = nameof(OnPropertyChanged))]
    public partial float B { get; set; } = 0.0f;
    [BindableProperty(PropertyChangedMethodName = nameof(OnPropertyChanged))]
    public partial float A { get; set; } = 0.0f;
    static void OnPropertyChanged(BindableObject b, object o, object n)
        =&gt; ((RgbColorExtension)b).UpdateResult();
    void UpdateResult()
        =&gt; Result = Color.FromRgba(R, G, B, A);
}
</code></pre>
<pre class="lang-cs prettyprint-override"><code>public partial class BindableObjectMarkupExtension&lt;T&gt; : BindableObject, IMarkupExtension&lt;BindingBase&gt;
{
    T? result;
    public T? Result
    {
        get =&gt; result;
        set { result = value; OnPropertyChanged(nameof(Result)); }
    }
    public object ProvideValue(IServiceProvider serviceProvider) =&gt; (this as IMarkupExtension&lt;BindingBase&gt;).ProvideValue(serviceProvider);
    BindingBase IMarkupExtension&lt;BindingBase&gt;.ProvideValue(IServiceProvider serviceProvider)
    {
        if (serviceProvider.GetService(typeof(IProvideValueTarget)) is IProvideValueTarget provideValueTarget &amp;&amp; provideValueTarget.TargetObject is BindableObject targetObject)
        {
            this.SetBinding(BindingContextProperty, new Binding(&quot;BindingContext&quot;, BindingMode.OneWay, source: targetObject));
        }
        return new Binding(&quot;Result&quot;, BindingMode.OneWay, source: this);
    }
}
</code></pre>
